UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Vickiana — Ana Victoria García Pérez, born in Santiago de los Caballeros on 15 July 1958 — is a Dominican singer, vedette and television presenter, and the defining female soloist of Dominican popular music in the 1980s. She won the singer category at the first «Premios Casandra» in 1985, over ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f84b208b-dd57-43ad-b2bf-d5099e2f0e0e","displayText":"Olga Lara","occurrenceId":"00f5ec5e-9b9e-4eab-940b-66009b4631d7"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"081c1484-bf1c-4b11-ba01-d68446b7b111","displayText":"Anthony Ríos","occurrenceId":"384dc5dd-3c86-4824-97d5-ec13e33bf65f"}},{"text":", and three decades later received the «Soberano al Mérito» on the same night as Lara, her rival for most of that time.","type":"text"}]},{"type":"paragraph","content":[{"text":"From Tamboril to Providence","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"She was raised by her grandparents in Tamboril, in Santiago province, and married at seventeen. A spell in Providence, Rhode Island, working in a factory, left her speaking Portuguese before she came back to record. She was earning her living as a seamstress when Luis Martínez Diloné, later her manager, discovered her at the end of the 1970s, and her professional debut came on «Fiesta», on «Tele Antillas». Her first single was «Besarte y amarte», which he wrote and credited to her, backed with Nelson Ned’s «Yo quisiera vivir».","type":"text"}]},{"type":"paragraph","content":[{"text":"The eighties","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"«Jardín prohibido» (1981), «Te invito» (1983) and «Derríteme» (1985) made her one of the very few female soloists at the top of the Dominican charts; the backing vocals on the last of them were sung by the leader of ","type":