UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Roger Zayas-Bazán —born in Santo Domingo on 2 August 1961— is a Dominican musician and, since the group’s founding in the early 1980s, the only original member remaining alongside Juan Luis Guerra himself in ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"00767839-a43b-4218-8fbb-56086d7e740d"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"From rock bands to a jingle studio","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He began musical training at ten and was recording radio and television jingles by fourteen. At fifteen he joined the rock group Juventud ’75 with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"b1dec30a-6da0-442a-be24-9891c4ddbe53","displayText":"Alex Mansilla","occurrenceId":"cd3e504a-895b-4eb9-be74-3966b5f0c470"}},{"text":" and Carolina Hernández, and the following year founded Nasty with them and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c7651bfb-598e-4877-9b65-323df1fcfd70","displayText":"Marco Hernández","occurrenceId":"758dfcd3-96db-435d-8954-13f2d0a4a407"}},{"text":". At eighteen, a cultural exchange program took him to the United States for a year, playing in Columbia High School’s jazz band and marching band; back home, he founded Friends, which performed with the National Symphony Orchestra in 1984, while working as a sound engineer at Estudios Ecmas.","type":"text"}]},{"type":"paragraph","content":[{"text":"An accidental quartet","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Zayas met Juan Luis Guerra when his own first job as a sound engineer coincided with Guerra’s first job writing radio jingles. Together with Mariela Mercado, from the group Módulo, and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"080c0205-8b66-4f16-915e-1d867acf82cc","displayText":"Maridalia Hernández","occurrenceId":"e7b7fd66-d937-4e07-85c3-9061a89698ce"}},{"text":", they formed an impromptu vocal quartet to dust off a cappella transcriptions Guerra had been assigned as homework at Berklee, taking the name «4.40» from the universal tuning pitch. Their 1984 debut album, «Soplando», fused merengue with Manhattan Transfer-style jazz vocal harmony and sold poorly for being too soft to dance to — it was later reissued by Warner in 1991 as a collector’s item. Karen Records only signed the group once they proved, with «Por Eso Ahora», that they could make a livelier record.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tragedy on tour","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"A car accident during a 1988 tour of Venezuela with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas","occurrenceId":"fb085a63-efc2-4f99-9ad4-b8d1e1c1debb"}},{"text":" killed several people, including the percussionist Ángel «Catarey» Andújar, and silenced the group for a year. On their return in 1989 they assembled a touring band for the first time — until then they had performed to prerecorded tracks — and that same year «Ojalá Que Llueva Café» became their international breakthrough.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Through the group’s later albums, from «Areíto» (1992) to «Fogaraté» (1994) — during whose recording Zayas was widowed and left raising his young son alone, with Guerra’s personal support — and on through «Ni Es lo Mismo Ni Es Igual» (1999) and beyond, including a period with singer ","type":"text"},{"type":"artistReference","attrs":{"artistId":"79d013c7-dafc-4807-966e-32c370172dee","displayText":"Adalgisa Pantaleón","occurrenceId":"4749d033-2ba4-4f07-90b2-3d1456df68ea"}},{"text":", Zayas has remained the group’s sole original member besides its leader. He describes himself as 4.40’s number one fan and says he has no plans to retire.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'roger-zayas-bazan' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Roger Zayas-Bazán —born in Santo Domingo on 2 August 1961— is a Dominican musician and, since the group’s founding in the early 1980s, the only original member remaining alongside Juan Luis Guerra himself in Juan Luis Guerra 4.40.

**From rock bands to a jingle studio**

He began musical training at ten and was recording radio and television jingles by fourteen. At fifteen he joined the rock group Juventud ’75 with Alex Mansilla and Carolina Hernández, and the following year founded Nasty with them and Marco Hernández. At eighteen, a cultural exchange program took him to the United States for a year, playing in Columbia High School’s jazz band and marching band; back home, he founded Friends, which performed with the National Symphony Orchestra in 1984, while working as a sound engineer at Estudios Ecmas.

**An accidental quartet**

Zayas met Juan Luis Guerra when his own first job as a sound engineer coincided with Guerra’s first job writing radio jingles. Together with Mariela Mercado, from the group Módulo, and Maridalia Hernández, they formed an impromptu vocal quartet to dust off a cappella transcriptions Guerra had been assigned as homework at Berklee, taking the name «4.40» from the universal tuning pitch. Their 1984 debut album, «Soplando», fused merengue with Manhattan Transfer-style jazz vocal harmony and sold poorly for being too soft to dance to — it was later reissued by Warner in 1991 as a collector’s item. Karen Records only signed the group once they proved, with «Por Eso Ahora», that they could make a livelier record.

**Tragedy on tour**

A car accident during a 1988 tour of Venezuela with Sergio Vargas killed several people, including the percussionist Ángel «Catarey» Andújar, and silenced the group for a year. On their return in 1989 they assembled a touring band for the first time — until then they had performed to prerecorded tracks — and that same year «Ojalá Que Llueva Café» became their international breakthrough.

**Legacy**

Through the group’s later albums, from «Areíto» (1992) to «Fogaraté» (1994) — during whose recording Zayas was widowed and left raising his young son alone, with Guerra’s personal support — and on through «Ni Es lo Mismo Ni Es Igual» (1999) and beyond, including a period with singer Adalgisa Pantaleón, Zayas has remained the group’s sole original member besides its leader. He describes himself as 4.40’s number one fan and says he has no plans to retire.' WHERE slug = 'roger-zayas-bazan';
