INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'roger-zayas-bazan' AND d.locale = 'en' AND d.document_type = 'artist_biography'), '4749d033-2ba4-4f07-90b2-3d1456df68ea', 'artist', '79d013c7-dafc-4807-966e-32c370172dee');

