INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'manolin-gonzalez' AND d.locale = 'en' AND d.document_type = 'artist_biography'), 'c0cae260-96c5-40cf-a5aa-038bfb01b36e', 'artist', '2dde2335-84c3-49ba-be43-f3c3ae717d87');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Mario Rivera —nacido en Santo Domingo el 22 de julio de 1939 y fallecido en Nueva York el 10 de agosto de 2007— fue saxofonista, multiinstrumentista, compositor y arreglista dominicano, y durante más de cuatro décadas uno de los músicos acompañantes más solicitados del jazz, el jazz latino y la salsa de Nueva York. Conocido como El Comandante, fue pieza fija de los conjuntos de jazz latino de Tito Puente y grabó un solo disco como líder, una fusión de merengue y jazz.","type":"text"}]},{"type":"paragraph","content":[{"text":"De Santo Domingo a Nueva York","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Se mudó a Nueva York en 1961, a los veintidós años, y empezó acompañando al cantante puertorriqueño Joe Valle; de 1963 a 1965 tocó con Tito Rodríguez. Antes de que la migración dominicana de los ochenta transformara Washington Heights, era, con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e005898c-4fcc-45da-b857-c6775e92fa52","displayText":"Johnny Pacheco","occurrenceId":"277d8902-d9eb-44a6-85fe-bdc832c7ddda"}},{"text":", una figura dominicana destacada en una escena latina dominada por puertorriqueños y cubanos.","type":"text"}]},{"type":"paragraph","content":[{"text":"Una casa llena de instrumentos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"El saxofón era su instrumento principal, y tocaba toda la familia —soprano, alto, tenor y barítono— a nivel de solista; fue además uno de los pocos saxofonistas que dominaron la flauta al estilo de la charanga cubana, y tocaba trompeta, piano, vibráfono, batería, timbales y congas. Le gustaba decir que tocaba veinticuatro instrumentos. Su apartamento del Upper West Side de Manhattan estaba lleno de ellos, y a los amigos que llegaban después de tocar les ponía uno en las manos para improvisar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Con los maestros","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su solo de barítono en «Mambo a la Tito», del disco «20th Anniversary» (1967) de Tito Puente, es una buena puerta de entrada a su forma de tocar, y en las décadas siguientes se convirtió en el motor discreto del conjunto de jazz latino de Puente. Trabajó también con Machito, Sonny Stitt, Charlie y Eddie Palmieri —en «Sentido» (1973), de Palmieri, presenta «No pienses así» y casi se adueña del tema—, «Típica 73», el octeto de George Coleman, los Jazz Masters de Slide Hampton, la orquesta de Chico O’Farrill y, desde 1988, la United Nation Orchestra de Dizzy Gillespie. Apareció con Puente en las películas «The Mambo Kings» y «Calle 54». Cuando el merengue se adueñó de Nueva York en los ochenta y noventa, las estrellas dominicanas de visita iban a su casa a presentarle sus respetos; tocó en «Así soy yo» (1984), de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc310977-31a9-41bb-9af2-7d3a0d7fabdd","displayText":"Fernando Villalona","occurrenceId":"c7a15320-02f4-4eec-afc1-f949ff6e9d7c"}},{"text":", y en «Fogaraté!» (1994), de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"4d363e38-8cbd-4de4-9973-f4af9379aef4"}},{"text":", y compartió escenario y grabaciones con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e8ba0f32-1d96-494d-9861-b1dc3937331e","displayText":"José Alberto \"El Canario\"","occurrenceId":"22cce5d7-b649-4ac2-9c9f-1d60511738af"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"«El Comandante»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Dirigió dos grupos propios. «Salsa Refugees» fue una vía de escape de los límites de la salsa y un campo de entrenamiento para músicos jóvenes como Andy y Jerry González, Steve Turre y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"da791d26-8bab-45e4-b7d1-f09314869f09","displayText":"Michel Camilo","occurrenceId":"de30bf36-f234-444a-8eec-d0a4c40502f7"}},{"text":"; el Mario Rivera Sextet no dejó grabaciones. A mediados de los noventa publicó su único disco como líder, «El Comandante», que enfrentaba de manera sistemática el merengue con la improvisación del jazz y rendía homenaje a su modelo, el saxofonista dominicano Tavito Vásquez. Al principio pasó casi inadvertido, algo que le dolió.","type":"text"}]},{"type":"paragraph","content":[{"text":"Maestro de maestros","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Los músicos jóvenes lo buscaban: ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0dee2e87-7680-4300-8038-a57c419e76c3","displayText":"Crispín Fernández","occurrenceId":"0ee421ea-16a3-49d1-89c0-a7968f8b7d88"}},{"text":" estudió con él armonía y técnica del saxofón. En enero de 2007, siete meses antes de morir, el trombonista Conrad Herwig lo presentó en escena como «nuestro padre», y su último solo grabado, en saxo soprano, fue «Flamenco Mood» con los Latin Giants of Jazz. Tras su muerte, la Afro Latin Jazz Orchestra de Arturo O’Farrill tocó en su servicio conmemorativo en Manhattan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Mario Rivera hizo su carrera en las bandas de otros, y sus colegas lo tenían por un músico de músicos y, por derecho propio, una leyenda. Su único disco sigue siendo un intento poco común y sostenido de unir merengue y jazz, y su nombre se cita entre los músicos latinos cuyo papel en la historia del jazz ha sido largamente ignorado.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'mario-rivera' AND d.locale = 'es' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_es = 'Mario Rivera —nacido en Santo Domingo el 22 de julio de 1939 y fallecido en Nueva York el 10 de agosto de 2007— fue saxofonista, multiinstrumentista, compositor y arreglista dominicano, y durante más de cuatro décadas uno de los músicos acompañantes más solicitados del jazz, el jazz latino y la salsa de Nueva York. Conocido como El Comandante, fue pieza fija de los conjuntos de jazz latino de Tito Puente y grabó un solo disco como líder, una fusión de merengue y jazz.

**De Santo Domingo a Nueva York**

Se mudó a Nueva York en 1961, a los veintidós años, y empezó acompañando al cantante puertorriqueño Joe Valle; de 1963 a 1965 tocó con Tito Rodríguez. Antes de que la migración dominicana de los ochenta transformara Washington Heights, era, con Johnny Pacheco, una figura dominicana destacada en una escena latina dominada por puertorriqueños y cubanos.

**Una casa llena de instrumentos**

El saxofón era su instrumento principal, y tocaba toda la familia —soprano, alto, tenor y barítono— a nivel de solista; fue además uno de los pocos saxofonistas que dominaron la flauta al estilo de la charanga cubana, y tocaba trompeta, piano, vibráfono, batería, timbales y congas. Le gustaba decir que tocaba veinticuatro instrumentos. Su apartamento del Upper West Side de Manhattan estaba lleno de ellos, y a los amigos que llegaban después de tocar les ponía uno en las manos para improvisar.

**Con los maestros**

Su solo de barítono en «Mambo a la Tito», del disco «20th Anniversary» (1967) de Tito Puente, es una buena puerta de entrada a su forma de tocar, y en las décadas siguientes se convirtió en el motor discreto del conjunto de jazz latino de Puente. Trabajó también con Machito, Sonny Stitt, Charlie y Eddie Palmieri —en «Sentido» (1973), de Palmieri, presenta «No pienses así» y casi se adueña del tema—, «Típica 73», el octeto de George Coleman, los Jazz Masters de Slide Hampton, la orquesta de Chico O’Farrill y, desde 1988, la United Nation Orchestra de Dizzy Gillespie. Apareció con Puente en las películas «The Mambo Kings» y «Calle 54». Cuando el merengue se adueñó de Nueva York en los ochenta y noventa, las estrellas dominicanas de visita iban a su casa a presentarle sus respetos; tocó en «Así soy yo» (1984), de Fernando Villalona, y en «Fogaraté!» (1994), de Juan Luis Guerra 4.40, y compartió escenario y grabaciones con José Alberto "El Canario".

**«El Comandante»**

Dirigió dos grupos propios. «Salsa Refugees» fue una vía de escape de los límites de la salsa y un campo de entrenamiento para músicos jóvenes como Andy y Jerry González, Steve Turre y Michel Camilo; el Mario Rivera Sextet no dejó grabaciones. A mediados de los noventa publicó su único disco como líder, «El Comandante», que enfrentaba de manera sistemática el merengue con la improvisación del jazz y rendía homenaje a su modelo, el saxofonista dominicano Tavito Vásquez. Al principio pasó casi inadvertido, algo que le dolió.

**Maestro de maestros**

Los músicos jóvenes lo buscaban: Crispín Fernández estudió con él armonía y técnica del saxofón. En enero de 2007, siete meses antes de morir, el trombonista Conrad Herwig lo presentó en escena como «nuestro padre», y su último solo grabado, en saxo soprano, fue «Flamenco Mood» con los Latin Giants of Jazz. Tras su muerte, la Afro Latin Jazz Orchestra de Arturo O’Farrill tocó en su servicio conmemorativo en Manhattan.

**Legado**

Mario Rivera hizo su carrera en las bandas de otros, y sus colegas lo tenían por un músico de músicos y, por derecho propio, una leyenda. Su único disco sigue siendo un intento poco común y sostenido de unir merengue y jazz, y su nombre se cita entre los músicos latinos cuyo papel en la historia del jazz ha sido largamente ignorado.' WHERE slug = 'mario-rivera';
