UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Fernando Echavarría — born Fernando Arturo Echavarría Acosta on 14 August 1953 in Santo Domingo, died 11 October 2015 — was a Dominican singer, composer and bandleader, the creator of «fusón», a homegrown Dominican fusion style built on a merengue base.","type":"text"}]},{"type":"paragraph","content":[{"text":"A musical household","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was the son of the musician, composer, producer and comedian Babín Echavarría, and grew up between the Santo Domingo neighborhoods of San Carlos, San Juan Bosco and Gazcue.","type":"text"}]},{"type":"paragraph","content":[{"text":"«La Familia André» and «fusón»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In the early 1980s he founded «La Familia André» and, with it, the genre he named fusón: Afro-Antillean rhythms such as samba and cumbia layered with jazz and rock, held together by an underlying merengue pulse. «Pato robao», «Marcela» and «Donde e’ que e’» were among the group’s biggest hits; «Marcela» later opened ","type":"text"},{"type":"artistReference","attrs":{"artistId":"fb068903-a085-4a3f-b846-0be0b3e28934","displayText":"Henry García","occurrenceId":"92904c5c-e8e2-4d41-9827-eddf74cf7d36"}},{"text":"’s debut album with his own orchestra.","type":"text"}]},{"type":"paragraph","content":[{"text":"An influence, and a career in Colombia","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"0337dec9-fe9d-485f-be56-a9120b92fbe8","displayText":"Chichi Peralta","occurrenceId":"03d06afe-b76a-42c5-b7e3-6e522711c34d"}},{"text":" played percussion in La Familia André for seven years before forming his own group, Son Familia, and the DR Jazz Festival credits fusón’s blend of rhythms as an early influence on the fusion strain of Dominican music that later ran through acts such as ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"08a07f3f-bb76-4439-89f1-927d95f3172e"}},{"text":" and, in Colombia, Carlos Vives. Echavarría’s own songs found a particularly large audience in Colombia, where several became standards of popular music.","type":"text"}]},{"type":"paragraph","content":[{"text":"Recognition","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2006 Colombia’s Premios Luna paid him tribute as the international artist with the greatest influence on Colombian music over the previous two decades; in 2008 the Premios Casandra gave him its Honor al Mérito for a career already past twenty-five years; and in 2011 the state bank Banreservas declared him a Reserva Musical Nacional.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He died on 11 October 2015, at sixty-two, arriving at a Santo Domingo venue to perform. Weeks later, Colombia’s Premios Luna paid him a posthumous tribute, closing the circle of a career that had carried a homegrown Dominican fusion sound further afield than almost any of its time.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'fernando-echavarria' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Fernando Echavarría — born Fernando Arturo Echavarría Acosta on 14 August 1953 in Santo Domingo, died 11 October 2015 — was a Dominican singer, composer and bandleader, the creator of «fusón», a homegrown Dominican fusion style built on a merengue base.

**A musical household**

He was the son of the musician, composer, producer and comedian Babín Echavarría, and grew up between the Santo Domingo neighborhoods of San Carlos, San Juan Bosco and Gazcue.

**«La Familia André» and «fusón»**

In the early 1980s he founded «La Familia André» and, with it, the genre he named fusón: Afro-Antillean rhythms such as samba and cumbia layered with jazz and rock, held together by an underlying merengue pulse. «Pato robao», «Marcela» and «Donde e’ que e’» were among the group’s biggest hits; «Marcela» later opened Henry García’s debut album with his own orchestra.

**An influence, and a career in Colombia**

Chichi Peralta played percussion in La Familia André for seven years before forming his own group, Son Familia, and the DR Jazz Festival credits fusón’s blend of rhythms as an early influence on the fusion strain of Dominican music that later ran through acts such as Juan Luis Guerra 4.40 and, in Colombia, Carlos Vives. Echavarría’s own songs found a particularly large audience in Colombia, where several became standards of popular music.

**Recognition**

In 2006 Colombia’s Premios Luna paid him tribute as the international artist with the greatest influence on Colombian music over the previous two decades; in 2008 the Premios Casandra gave him its Honor al Mérito for a career already past twenty-five years; and in 2011 the state bank Banreservas declared him a Reserva Musical Nacional.

**Legacy**

He died on 11 October 2015, at sixty-two, arriving at a Santo Domingo venue to perform. Weeks later, Colombia’s Premios Luna paid him a posthumous tribute, closing the circle of a career that had carried a homegrown Dominican fusion sound further afield than almost any of its time.' WHERE slug = 'fernando-echavarria';
