UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Chichi Peralta —Pedro René Peralta Soto, nacido en Santo Domingo el 9 de julio de 1966— es percusionista, cantante, compositor, arreglista y productor dominicano. Pasó los años ochenta y noventa como percusionista de oficio, ocho de ellos en la agrupación de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"84c0ede6-7573-463a-a491-dfad7198d51b"}},{"text":", antes de lanzar «Chichi Peralta y Son Familia» y ganar un Grammy Latino en 2001 por «...De vuelta al barrio».","type":"text"}]},{"type":"paragraph","content":[{"text":"Una tambora a los cuatro años","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Peralta sitúa su comienzo a los cuatro años, cuando construyó su primer instrumento, una tambora. Por los ochenta y los noventa tocó percusión profesionalmente: primero en el «Grupo Fragmento», después siete años con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"29832daf-f093-4ccb-820d-441cdc3f48c0","displayText":"Fernando Echavarría","occurrenceId":"8a6593e7-e75f-473b-b607-7401a83893dd"}},{"text":" y la «Familia André», luego en «Trilogía», el trío de fusión que llevaba ","type":"text"},{"type":"artistReference","attrs":{"artistId":"8769e02a-52d7-4818-ac19-e5dd46d7075f","displayText":"Juan Francisco Ordóñez","occurrenceId":"42e6b522-b845-4fb6-a261-d3072ab921cd"}},{"text":" con el bajista Héctor Santana, y finalmente ocho años con Juan Luis Guerra. Compuso además música para documentales —«Trujillo: el poder del Jefe III», de 1996, y «Camino a Higüey», de 2016— y para publicidad.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Son Familia»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su primer disco, «Trópico adentro», salió en 1995. «Pa’ otro la’o» se lanzó internacionalmente el 15 de julio de 1997, con Peralta como productor y arreglista; de él salieron «Amor narcótico», «La ciguapa» y «Procura», y en los dos años siguientes el disco acumuló discos de oro y platino en Perú, Chile, Colombia, Bolivia y Centroamérica. Cartagena le entregó las llaves de la ciudad en junio de 1998.","type":"text"}]},{"type":"paragraph","content":[{"text":"«...De vuelta al barrio»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"El tercer álbum salió el 18 de abril de 2000 y ganó el Mejor Álbum de Merengue en la segunda edición de los Grammy Latinos, en 2001. Se grabó en París con la Orquesta Sinfónica de Londres y los coros de Luz África, y cruzó el son con el jazz, el merengue con el guaguancó y la bachata con figuras brasileñas y árabes. ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bd3ad92b-1a26-48dd-a667-8a0debeaf5a3","displayText":"Jandy Feliz","occurrenceId":"a36b2960-1358-499c-9bcd-f445c91996cb"}},{"text":" se había ido a trabajar por su cuenta, y entraron dos cantantes a sustituirlo: César Olarte, de Aruba, y René Geraldino.","type":"text"}]},{"type":"paragraph","content":[{"text":"Después","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"«Más que suficiente» salió el 27 de septiembre de 2005 y fue nominado a Mejor Álbum de Merengue/Bachata en los Grammy Latinos de 2006; estuvo entre las producciones latinas más vendidas en Japón. En 2007 fue declarado embajador de buena voluntad de la República Dominicana. «De aquel la’o del río» llegó en 2009 con «Amor samurái», armado con música caribeña e instrumentos tradicionales japoneses, y detrás vinieron «De que viene, viene» en 2012 y «Máscara contra cabellera» en 2013.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Los discos de Peralta suelen archivarse como world music por todo lo que admiten: el son con el jazz, el merengue con el pop, ritmos africanos, hip hop, bachata, guaguancó, figuras brasileñas y árabes, texturas sinfónicas, instrumentos de la India y de Japón. «Amor narcótico» volvió a grabarse en 2021, veinticuatro años después, por el grupo estadounidense «CNCO» en su disco de versiones «Déjà Vu».","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'chichi-peralta' AND d.locale = 'es' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_es = 'Chichi Peralta —Pedro René Peralta Soto, nacido en Santo Domingo el 9 de julio de 1966— es percusionista, cantante, compositor, arreglista y productor dominicano. Pasó los años ochenta y noventa como percusionista de oficio, ocho de ellos en la agrupación de Juan Luis Guerra 4.40, antes de lanzar «Chichi Peralta y Son Familia» y ganar un Grammy Latino en 2001 por «...De vuelta al barrio».

**Una tambora a los cuatro años**

Peralta sitúa su comienzo a los cuatro años, cuando construyó su primer instrumento, una tambora. Por los ochenta y los noventa tocó percusión profesionalmente: primero en el «Grupo Fragmento», después siete años con Fernando Echavarría y la «Familia André», luego en «Trilogía», el trío de fusión que llevaba Juan Francisco Ordóñez con el bajista Héctor Santana, y finalmente ocho años con Juan Luis Guerra. Compuso además música para documentales —«Trujillo: el poder del Jefe III», de 1996, y «Camino a Higüey», de 2016— y para publicidad.

**«Son Familia»**

Su primer disco, «Trópico adentro», salió en 1995. «Pa’ otro la’o» se lanzó internacionalmente el 15 de julio de 1997, con Peralta como productor y arreglista; de él salieron «Amor narcótico», «La ciguapa» y «Procura», y en los dos años siguientes el disco acumuló discos de oro y platino en Perú, Chile, Colombia, Bolivia y Centroamérica. Cartagena le entregó las llaves de la ciudad en junio de 1998.

**«...De vuelta al barrio»**

El tercer álbum salió el 18 de abril de 2000 y ganó el Mejor Álbum de Merengue en la segunda edición de los Grammy Latinos, en 2001. Se grabó en París con la Orquesta Sinfónica de Londres y los coros de Luz África, y cruzó el son con el jazz, el merengue con el guaguancó y la bachata con figuras brasileñas y árabes. Jandy Feliz se había ido a trabajar por su cuenta, y entraron dos cantantes a sustituirlo: César Olarte, de Aruba, y René Geraldino.

**Después**

«Más que suficiente» salió el 27 de septiembre de 2005 y fue nominado a Mejor Álbum de Merengue/Bachata en los Grammy Latinos de 2006; estuvo entre las producciones latinas más vendidas en Japón. En 2007 fue declarado embajador de buena voluntad de la República Dominicana. «De aquel la’o del río» llegó en 2009 con «Amor samurái», armado con música caribeña e instrumentos tradicionales japoneses, y detrás vinieron «De que viene, viene» en 2012 y «Máscara contra cabellera» en 2013.

**Legado**

Los discos de Peralta suelen archivarse como world music por todo lo que admiten: el son con el jazz, el merengue con el pop, ritmos africanos, hip hop, bachata, guaguancó, figuras brasileñas y árabes, texturas sinfónicas, instrumentos de la India y de Japón. «Amor narcótico» volvió a grabarse en 2021, veinticuatro años después, por el grupo estadounidense «CNCO» en su disco de versiones «Déjà Vu».' WHERE slug = 'chichi-peralta';
