UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Fernando Echavarría —nacido Fernando Arturo Echavarría Acosta el 14 de agosto de 1953 en Santo Domingo, fallecido el 11 de octubre de 2015— fue un cantante, compositor y director de orquesta dominicano, creador del «fusón», un estilo de fusión dominicano propio construido sobre una base de merengue.","type":"text"}]},{"type":"paragraph","content":[{"text":"Una casa de músicos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Era hijo del músico, compositor, productor y humorista Babín Echavarría, y creció entre los barrios San Carlos, San Juan Bosco y Gazcue, de Santo Domingo.","type":"text"}]},{"type":"paragraph","content":[{"text":"«La Familia André» y el «fusón»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"A inicios de los ochenta fundó «La Familia André» y, con ella, el género que llamó fusón: ritmos afroantillanos como la samba y la cumbia superpuestos al jazz y al rock, sostenidos por un pulso de fondo de merengue. «Pato robao», «Marcela» y «Donde e’ que e’» estuvieron entre los mayores éxitos del grupo; «Marcela» abrió después el disco debut de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"fb068903-a085-4a3f-b846-0be0b3e28934","displayText":"Henry García","occurrenceId":"54959cf4-3cab-4905-b34e-fbdc1212f6a2"}},{"text":" al frente de su propia orquesta.","type":"text"}]},{"type":"paragraph","content":[{"text":"Una influencia, y una carrera en Colombia","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"0337dec9-fe9d-485f-be56-a9120b92fbe8","displayText":"Chichi Peralta","occurrenceId":"3e083b16-c198-4c03-b3ab-4f9c9f1470c5"}},{"text":" tocó percusión en La Familia André durante siete años antes de formar su propio grupo, Son Familia, y el DR Jazz Festival atribuye a la mezcla de ritmos del fusón una influencia temprana sobre la vertiente de fusión de la música dominicana que después recorrió a artistas como ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"8a94d971-13bf-41d2-924d-6e5e2a828563"}},{"text":" y, en Colombia, Carlos Vives. Las propias canciones de Echavarría encontraron un público especialmente grande en Colombia, donde varias se volvieron clásicos populares.","type":"text"}]},{"type":"paragraph","content":[{"text":"Reconocimientos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 2006 los Premios Luna de Colombia le rindieron homenaje como el artista internacional de mayor influencia en la música colombiana de las dos décadas anteriores; en 2008 los Premios Casandra le dieron su Honor al Mérito por una carrera que ya pasaba de veinticinco años; y en 2011 el banco estatal Banreservas lo declaró Reserva Musical Nacional.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Murió el 11 de octubre de 2015, a los sesenta y dos años, al llegar a una tarima de Santo Domingo para presentarse. Semanas después, los Premios Luna de Colombia le rindieron un homenaje póstumo, cerrando el círculo de una carrera que llevó un sonido de fusión dominicano propio más lejos que casi ninguno de su época.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'fernando-echavarria' AND d.locale = 'es' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_es = 'Fernando Echavarría —nacido Fernando Arturo Echavarría Acosta el 14 de agosto de 1953 en Santo Domingo, fallecido el 11 de octubre de 2015— fue un cantante, compositor y director de orquesta dominicano, creador del «fusón», un estilo de fusión dominicano propio construido sobre una base de merengue.

**Una casa de músicos**

Era hijo del músico, compositor, productor y humorista Babín Echavarría, y creció entre los barrios San Carlos, San Juan Bosco y Gazcue, de Santo Domingo.

**«La Familia André» y el «fusón»**

A inicios de los ochenta fundó «La Familia André» y, con ella, el género que llamó fusón: ritmos afroantillanos como la samba y la cumbia superpuestos al jazz y al rock, sostenidos por un pulso de fondo de merengue. «Pato robao», «Marcela» y «Donde e’ que e’» estuvieron entre los mayores éxitos del grupo; «Marcela» abrió después el disco debut de Henry García al frente de su propia orquesta.

**Una influencia, y una carrera en Colombia**

Chichi Peralta tocó percusión en La Familia André durante siete años antes de formar su propio grupo, Son Familia, y el DR Jazz Festival atribuye a la mezcla de ritmos del fusón una influencia temprana sobre la vertiente de fusión de la música dominicana que después recorrió a artistas como Juan Luis Guerra 4.40 y, en Colombia, Carlos Vives. Las propias canciones de Echavarría encontraron un público especialmente grande en Colombia, donde varias se volvieron clásicos populares.

**Reconocimientos**

En 2006 los Premios Luna de Colombia le rindieron homenaje como el artista internacional de mayor influencia en la música colombiana de las dos décadas anteriores; en 2008 los Premios Casandra le dieron su Honor al Mérito por una carrera que ya pasaba de veinticinco años; y en 2011 el banco estatal Banreservas lo declaró Reserva Musical Nacional.

**Legado**

Murió el 11 de octubre de 2015, a los sesenta y dos años, al llegar a una tarima de Santo Domingo para presentarse. Semanas después, los Premios Luna de Colombia le rindieron un homenaje póstumo, cerrando el círculo de una carrera que llevó un sonido de fusión dominicano propio más lejos que casi ninguno de su época.' WHERE slug = 'fernando-echavarria';
