UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Henry García — Henry Hilton García Rosario, born in Santo Domingo on 13 September 1955 — is a Dominican singer and songwriter. He was the lead voice of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c11c2dda-ffa1-4f09-9d24-00dc4473bc8d","displayText":"Cuco Valoy","occurrenceId":"7d28b6a4-e8c2-4a55-8b96-b5f3f787f488"}},{"text":"’s orchestra in the late 1970s, when it sang «Nació varón» and «Cuatro personas», and has since led his own orchestra, sung with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando & Orquesta Internacional","occurrenceId":"9615ab2e-aa9a-4a07-bb9e-155a96035cfd"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"001831dd-3baa-4512-88f5-f420ec7c2619","displayText":"Pochy y su Cocoband","occurrenceId":"4c8d1c0c-67ef-4511-8224-192b6183642c"}},{"text":", spent decades as one of the busiest backing singers in Dominican studios, and written hits for other voices, among them «Me mata la soledad» for Tito Rojas and «En las nubes» for Manny Manuel.","type":"text"}]},{"type":"paragraph","content":[{"text":"Guitar lessons and La Barrica","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He started studying music and guitar at fifteen. At nineteen he turned professional with the group of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"a4b2104e-5b76-4e04-b9ac-dfe3f25ea71d","displayText":"Julito Deschamps","occurrenceId":"f582cd35-a4f7-434f-8a81-7f033c849805"}},{"text":" at La Barrica, a Santo Domingo nightspot, where he spent about a year sharing the stage with experienced players.","type":"text"}]},{"type":"paragraph","content":[{"text":"The voice of «Los Virtuosos»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"On 19 February 1977 he joined «Los Virtuosos», the band ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c11c2dda-ffa1-4f09-9d24-00dc4473bc8d","displayText":"Cuco Valoy","occurrenceId":"bf8ab12a-5996-4cb7-aac3-08ead7c27bda"}},{"text":" had built in the seventies and that later took the name «La Tribu» after a tour of Panama. García became its main singer. «Nació varón» and «Cuatro personas», from the band’s third album, «Un momento... llegaron los Virtuosos», are still credited to his voice, alongside «Se fue Daniel», «La temperatura» and «Morina», and the orchestra took them on tour through the United States, Central and South America and Europe. In 1980 ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c11c2dda-ffa1-4f09-9d24-00dc4473bc8d","displayText":"Cuco Valoy","occurrenceId":"2c1cc3b3-11c5-472c-b1d1-275453796734"}},{"text":"’s orchestra also recorded the first song García wrote, «Cuando te entregué mi amor».","type":"text"}]},{"type":"paragraph","content":[{"text":"His own orchestra and the Internacional","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 1984 he left to form «Henry García y Orquesta». The first album featured «Marcela», by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"29832daf-f093-4ccb-820d-441cdc3f48c0","displayText":"Fernando Echavarría","occurrenceId":"86b860b4-3db1-4f6e-bbd9-c45ec04a45df"}},{"text":", and «Volverte a encontrar», one of his own. In 1986 he and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bb114227-a160-4f45-960e-b6c1710fbeef","displayText":"Peter Cruz","occurrenceId":"766a5101-9ea1-47f6-b582-2b2ba0bd13eb"}},{"text":" were the voices of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando & Orquesta Internacional","occurrenceId":"eacd6f85-66ad-42cc-8a24-53a63777d62b"}},{"text":", whose hits of that stage include «Lágrimas de amor» and «Cómo te atreves». He then went back to his