UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Sharlene, de nombre Sharlene Taulé Ponciano y nacida en Santo Domingo, es cantante, compositora y actriz dominicana. Se formó como música antes que como cualquier otra cosa, y las dos carreras llevan veinte años alimentándose entre sí.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dos formaciones","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Estudió música con la cantante española María Remola y actuación en el Instituto Lee Strasberg de Nueva York. Toca guitarra, piano y batería, canta como mezzosoprano y habla cuatro idiomas.","type":"text"}]},{"type":"paragraph","content":[{"text":"La actuación llegó primero por lo comercial: cine desde 2005, después televisión, después seis musicales, y el papel de María Teresa Mirabal en una película sobre las hermanas. También fue la protagonista del video de Bendita Tu Luz, de Maná y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"59c0f147-440c-4ac8-a31e-3f14cd5da6ad"}},{"text":", que es el primer sitio donde un público dominicano le vio la cara pegada a una música.","type":"text"}]},{"type":"paragraph","content":[{"text":"Lo que cambió la balanza fue una serie infantil. Interpretar a Katty en la Grachi de Nickelodeon la puso delante de un público de toda América Latina, Europa y Asia, y la gira en vivo que salió de ahí fue lo que le permitió volver a cantar como carrera y no como cosa aparte.","type":"text"}]},{"type":"paragraph","content":[{"text":"Toy Enamorao","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Debutó como solista en 2014 con Mal de Amor, una bachata grabada con los venezolanos Servando & Florentino. Detrás vino Aquí Nadie Toca, con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"fa9cc802-28ca-4695-b585-f75aa90a2b6c","displayText":"Mozart La Para","occurrenceId":"26b734b0-1d45-4c9b-be04-ffbf36e78c9b"}},{"text":", que se llevó dos nominaciones en los Videoclip Awards dominicanos.","type":"text"}]},{"type":"paragraph","content":[{"text":"Después Toy Enamorao —el disco de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"fa9cc802-28ca-4695-b585-f75aa90a2b6c","displayText":"Mozart La Para","occurrenceId":"d76dfa9c-e0de-4b17-a7c3-f14259b6ebab"}},{"text":", con ella y Nacho adentro— llegó al número uno de la lista Tropical Songs de Billboard. La Fila, el mismo año, la puso con Don Omar y Maluma en un álbum de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ef56311a-ac4b-451e-a7a7-97e5f240cd47","displayText":"Luny Tunes","occurrenceId":"57c38c13-3f5e-4393-9445-7178d0a78e5e"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"El álbum homónimo salió en 2016. Universal Music la firmó en febrero de 2017 y con eso llegó Encanto.","type":"text"}]},{"type":"paragraph","content":[{"text":"Viaje, y después","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Los sencillos no pararon —Me Siento Bien, Yo Pago Lo Mío, El Vecino, Lento, San Pedro, Quién Dijo Miedo, Aerofobia— con colaboradores de seis países, que es una descripción justa de dónde está de verdad su carrera.","type":"text"}]},{"type":"paragraph","content":[{"text":"Viaje llegó en 2020. Firmó con Warner Music México en 2021 y publicó Todo Pasa y Dopamina.","type":"text"}]},{"type":"paragraph","content":[{"text":"También ha hecho cuatro bandas sonoras —Grachi, Pasión Prohibida, Strings y Star— y cantó Vives en Mí para la segunda. Una cantante dominicana con un contrato de Universal, otro de Warner y un número uno de Billboard no es cosa corriente, y menos una que llegó ahí pasando por un set de Nickelodeon.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'sharlene' AND d.locale = 'es' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_es = 'Sharlene, de nombre Sharlene Taulé Ponciano y nacida en Santo Domingo, es cantante, compositora y actriz dominicana. Se formó como música antes que como cualquier otra cosa, y las dos carreras llevan veinte años alimentándose entre sí.

**Dos formaciones**

Estudió música con la cantante española María Remola y actuación en el Instituto Lee Strasberg de Nueva York. Toca guitarra, piano y batería, canta como mezzosoprano y habla cuatro idiomas.

La actuación llegó primero por lo comercial: cine desde 2005, después televisión, después seis musicales, y el papel de María Teresa Mirabal en una película sobre las hermanas. También fue la protagonista del video de Bendita Tu Luz, de Maná y Juan Luis Guerra 4.40, que es el primer sitio donde un público dominicano le vio la cara pegada a una música.

Lo que cambió la balanza fue una serie infantil. Interpretar a Katty en la Grachi de Nickelodeon la puso delante de un público de toda América Latina, Europa y Asia, y la gira en vivo que salió de ahí fue lo que le permitió volver a cantar como carrera y no como cosa aparte.

**Toy Enamorao**

Debutó como solista en 2014 con Mal de Amor, una bachata grabada con los venezolanos Servando & Florentino. Detrás vino Aquí Nadie Toca, con Mozart la Para, que se llevó dos nominaciones en los Videoclip Awards dominicanos.

Después Toy Enamorao —el disco de Mozart la Para, con ella y Nacho adentro— llegó al número uno de la lista Tropical Songs de Billboard. La Fila, el mismo año, la puso con Don Omar y Maluma en un álbum de Luny Tunes.

El álbum homónimo salió en 2016. Universal Music la firmó en febrero de 2017 y con eso llegó Encanto.

**Viaje, y después**

Los sencillos no pararon —Me Siento Bien, Yo Pago Lo Mío, El Vecino, Lento, San Pedro, Quién Dijo Miedo, Aerofobia— con colaboradores de seis países, que es una descripción justa de dónde está de verdad su carrera.

Viaje llegó en 2020. Firmó con Warner Music México en 2021 y publicó Todo Pasa y Dopamina.

También ha hecho cuatro bandas sonoras —Grachi, Pasión Prohibida, Strings y Star— y cantó Vives en Mí para la segunda. Una cantante dominicana con un contrato de Universal, otro de Warner y un número uno de Billboard no es cosa corriente, y menos una que llegó ahí pasando por un set de Nickelodeon.' WHERE slug = 'sharlene';
