UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Sandy Gabriel — Sandy Antonio Gabriel Difó, born 10 May 1972 in Nagua — is a Dominican saxophonist, composer and arranger who built the country’s clearest bridge between jazz and merengue from a base on the north coast.","type":"text"}]},{"type":"paragraph","content":[{"text":"The Combo Candela","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He moved to Puerto Plata at nine; his interest in the saxophone came from his father, Sócrates Gabriel, who led the popular 1960s and ’70s group «Combo Candela». Sandy’s own early work was in jazz combos at Puerto Plata’s tourist hotels, where he began fusing jazz language with Dominican merengue.","type":"text"}]},{"type":"paragraph","content":[{"text":"From Puerto Plata to the world","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He went on to play the Puerto Plata Jazz Festival and Puerto Rico’s Heineken Jazz Festival, sharing stages there with Néstor Torres, Tito Puente, Sérgio Mendes, Spyro Gyra, Paquito D’Rivera, Chucho Valdés, Dave Grusin, Lee Ritenour, Arturo Sandoval and Gonzalo Rubalcaba, and carried his own «PP Jazz Ensemble» to the Ramajay Jazz Festival in Trinidad and Tobago, Cuba’s Jazz Plaza, the Bahamas Jazz Festival and the Montreal Jazz Festival. In the Dominican Republic he has recorded and performed with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"e340824f-e0c5-4899-b587-3e992ee5a5e5"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"da791d26-8bab-45e4-b7d1-f09314869f09","displayText":"Michel Camilo","occurrenceId":"7781df4d-ad33-4fc7-814f-1bd8a4596d96"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"4b4bf9da-fe4a-4fc6-be40-1b1b5413dfb3","displayText":"Víctor Víctor","occurrenceId":"b04d6438-d671-4dc0-8503-a6625fd6ec08"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"8769e02a-52d7-4818-ac19-e5dd46d7075f","displayText":"Juan Francisco Ordóñez","occurrenceId":"ffbabc73-85de-4eb6-a2e0-22aa1d710060"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0337dec9-fe9d-485f-be56-a9120b92fbe8","displayText":"Chichi Peralta","occurrenceId":"74d7fcd9-ca63-405d-a8c6-1ddec3f4921b"}},{"text":" and the percussionist ","type":"text"},{"type":"artistReference","attrs":{"artistId":"977db71a-8bf6-4006-a63d-5e604e99336c","displayText":"Guarionex Aquino Hijo","occurrenceId":"bf161bd9-619e-4da5-a52d-cd419117acb4"}},{"text":", with whom he has repeatedly shared a bill.","type":"text"}]},{"type":"paragraph","content":[{"text":"Awards, and the Teatro Nacional","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He won the 2003 Premio Nacional de Música in jazz and the 2012 Premios Casandra for Concierto del Año, and was the first Dominican jazz musician to bring an original show of his own to the Teatro Nacional. He has also taught saxophone, giving masterclasses for three straight years at the University of North Carolina and running clinics at Troy University in Alabama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Two decades after leaving hotel lounges in Puerto Plata for international stages, Gabriel remains the Dominican north’s clearest jazz voice, still touring under the PP Jazz Ensemble name that carries his adopted city’s initials.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'sandy-gabriel' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Sandy Gabriel — Sandy Antonio Gabriel Difó, born 10 May 1972 in Nagua — is a Dominican saxophonist, composer and arranger who built the country’s clearest bridge between jazz and merengue from a base on the north coast.

**The Combo Candela**

He moved to Puerto Plata at nine; his interest in the saxophone came from his father, Sócrates Gabriel, who led the popular 1960s and ’70s group «Combo Candela». Sandy’s own early work was in jazz combos at Puerto Plata’s tourist hotels, where he began fusing jazz language with Dominican merengue.

**From Puerto Plata to the world**

He went on to play the Puerto Plata Jazz Festival and Puerto Rico’s Heineken Jazz Festival, sharing stages there with Néstor Torres, Tito Puente, Sérgio Mendes, Spyro Gyra, Paquito D’Rivera, Chucho Valdés, Dave Grusin, Lee Ritenour, Arturo Sandoval and Gonzalo Rubalcaba, and carried his own «PP Jazz Ensemble» to the Ramajay Jazz Festival in Trinidad and Tobago, Cuba’s Jazz Plaza, the Bahamas Jazz Festival and the Montreal Jazz Festival. In the Dominican Republic he has recorded and performed with Juan Luis Guerra 4.40, Michel Camilo, Víctor Víctor, Juan Francisco Ordóñez, Chichi Peralta and the percussionist Guarionex Aquino Hijo, with whom he has repeatedly shared a bill.

**Awards, and the Teatro Nacional**

He won the 2003 Premio Nacional de Música in jazz and the 2012 Premios Casandra for Concierto del Año, and was the first Dominican jazz musician to bring an original show of his own to the Teatro Nacional. He has also taught saxophone, giving masterclasses for three straight years at the University of North Carolina and running clinics at Troy University in Alabama.

**Legacy**

Two decades after leaving hotel lounges in Puerto Plata for international stages, Gabriel remains the Dominican north’s clearest jazz voice, still touring under the PP Jazz Ensemble name that carries his adopted city’s initials.' WHERE slug = 'sandy-gabriel';
