UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Henry García —Henry Hilton García Rosario, nacido en Santo Domingo el 13 de septiembre de 1955— es cantante y compositor dominicano. Fue la voz principal de la orquesta de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c11c2dda-ffa1-4f09-9d24-00dc4473bc8d","displayText":"Cuco Valoy","occurrenceId":"c7a6847f-425d-481d-add7-3a8f188ff3cb"}},{"text":" a finales de los setenta, la de «Nació varón» y «Cuatro personas», y desde entonces ha dirigido su propia orquesta, ha cantado con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando & Orquesta Internacional","occurrenceId":"cbd9ea5c-1e7b-44df-89a1-b07f9796c36f"}},{"text":" y con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"001831dd-3baa-4512-88f5-f420ec7c2619","displayText":"Pochy y su Cocoband","occurrenceId":"6248f3a8-c082-4e04-b419-528a960d1c9b"}},{"text":", ha pasado décadas como uno de los coristas más solicitados de los estudios dominicanos y ha escrito éxitos para otras voces, entre ellos «Me mata la soledad» para Tito Rojas y «En las nubes» para Manny Manuel.","type":"text"}]},{"type":"paragraph","content":[{"text":"La guitarra y La Barrica","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Empezó a estudiar música y guitarra a los quince años. A los diecinueve se hizo profesional con el grupo de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"a4b2104e-5b76-4e04-b9ac-dfe3f25ea71d","displayText":"Julito Deschamps","occurrenceId":"92fba4f7-7585-4a41-ae71-e0d6791eff31"}},{"text":" en La Barrica, un local nocturno de Santo Domingo, donde pasó cerca de un año compartiendo tarima con músicos de oficio.","type":"text"}]},{"type":"paragraph","content":[{"text":"La voz de «Los Virtuosos»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","cont