UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Alex Ferreira —full name Alexandre Santiago Ferreira Peguero, born in Santo Domingo on 23 March 1983— is a Dominican-Spanish singer-songwriter, producer and sound engineer whose independent pop-rock career has taken him from Madrid to Mexico City, earning a nomination for Best New Artist at the 2018 Latin Grammy Awards.","type":"text"}]},{"type":"paragraph","content":[{"text":"From Santo Domingo to Madrid, with no return ticket","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He moved to the United States with his mother as a young child, spending his childhood and adolescence there, before relocating to Spain and settling in Madrid to study sound engineering while building a music career, working his way from central bars to larger venues. His earliest Dominican releases — the EP «Resplandor» (2003) and the 250-copy album «Parto Mi Viaje» (2005) — were known only to fans back home before he left the country with no ticket back.","type":"text"}]},{"type":"paragraph","content":[{"text":"A Spanish recording career","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2006 he signed a publishing deal with EMI Music Publishing Spain, releasing the acoustic EP «Un Domingo Cualquiera» (2007), and in 2008 a recording contract with Warner/DRO Music Spain, which released his EP «Serenata de Plástico»; that year Casa América and the magazine Fusión Latina named him among the 100 most influential Latinos of 2008. A further EP, «Páginas», followed in 2009, and in January 2010 his first full-length international album, also titled «Un Domingo Cualquiera», was praised by Spain’s Radio 3 as one of the year’s most anticipated releases and reached the top of the sales chart at Madrid’s Fnac Callao in its first week.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mexico City, and «Canapé»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"After touring Mexico and the United States, Ferreira relocated to Mexico City, where he reconnected with his Dominican roots and his New York childhood. His second album, «El Afán», appeared in 2012, followed by the more electronic «Cinema Tropical» (2015) and, in 2017, the crowdfunded «Canapé», which he described as a synthesis of his Afro-Antillean roots in bachata and merengue alongside his love of rock, pop and electronic music — proud, in his own words, to be a fan of both ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"e5668e6a-c03b-47a1-ab33-8c468e552b18"}},{"text":" and Björk.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Ferreira’s 2018 Latin Grammy nomination for Best New Artist followed, and he has continued releasing music with «Tanda» (2021) and «Versiones Para el Tiempo y la Distancia» (2024). He holds Dominican and Spanish citizenship and has a daughter, Uma Ferreira Moreno.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'alex-ferreira' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Alex Ferreira —full name Alexandre Santiago Ferreira Peguero, born in Santo Domingo on 23 March 1983— is a Dominican-Spanish singer-songwriter, producer and sound engineer whose independent pop-rock career has taken him from Madrid to Mexico City, earning a nomination for Best New Artist at the 2018 Latin Grammy Awards.

**From Santo Domingo to Madrid, with no return ticket**

He moved to the United States with his mother as a young child, spending his childhood and adolescence there, before relocating to Spain and settling in Madrid to study sound engineering while building a music career, working his way from central bars to larger venues. His earliest Dominican releases — the EP «Resplandor» (2003) and the 250-copy album «Parto Mi Viaje» (2005) — were known only to fans back home before he left the country with no ticket back.

**A Spanish recording career**

In 2006 he signed a publishing deal with EMI Music Publishing Spain, releasing the acoustic EP «Un Domingo Cualquiera» (2007), and in 2008 a recording contract with Warner/DRO Music Spain, which released his EP «Serenata de Plástico»; that year Casa América and the magazine Fusión Latina named him among the 100 most influential Latinos of 2008. A further EP, «Páginas», followed in 2009, and in January 2010 his first full-length international album, also titled «Un Domingo Cualquiera», was praised by Spain’s Radio 3 as one of the year’s most anticipated releases and reached the top of the sales chart at Madrid’s Fnac Callao in its first week.

**Mexico City, and «Canapé»**

After touring Mexico and the United States, Ferreira relocated to Mexico City, where he reconnected with his Dominican roots and his New York childhood. His second album, «El Afán», appeared in 2012, followed by the more electronic «Cinema Tropical» (2015) and, in 2017, the crowdfunded «Canapé», which he described as a synthesis of his Afro-Antillean roots in bachata and merengue alongside his love of rock, pop and electronic music — proud, in his own words, to be a fan of both Juan Luis Guerra 4.40 and Björk.

**Legacy**

Ferreira’s 2018 Latin Grammy nomination for Best New Artist followed, and he has continued releasing music with «Tanda» (2021) and «Versiones Para el Tiempo y la Distancia» (2024). He holds Dominican and Spanish citizenship and has a daughter, Uma Ferreira Moreno.' WHERE slug = 'alex-ferreira';
